"""GridWise Energy Monitor API server.

The application has two mutually exclusive operating modes:

* ``demo`` uses only synthetic readings generated by ``simulator.py``.
* ``hardware`` accepts readings from the future ESP32 + PZEM-004T device.

Both modes use the same MySQL schema and dashboard API. This keeps the demo
honest today while leaving the hardware integration path unchanged for later.
"""

from __future__ import annotations

import json
import os
import threading
import time
from datetime import datetime, timedelta
from http.server import BaseHTTPRequestHandler, HTTPServer
from pathlib import Path
from urllib.parse import parse_qs, urlparse

import mysql.connector
from mysql.connector import Error as MySQLError

try:
    from dotenv import load_dotenv

    ENV_FILE = Path(__file__).resolve().parent / ".env"
    if ENV_FILE.exists():
        load_dotenv(ENV_FILE)
except ImportError:
    pass


BASE_DIR = Path(__file__).resolve().parent
PROJECT_DIR = BASE_DIR.parent
INDEX_FILE = PROJECT_DIR / "web" / "index.html"
WEB_DIR = INDEX_FILE.parent

PORT = int(os.getenv("SERVER_PORT", "8000"))
DATA_MODE = os.getenv("DATA_MODE", "demo").strip().lower()
if DATA_MODE not in {"demo", "hardware"}:
    raise ValueError("DATA_MODE must be either 'demo' or 'hardware'.")
IS_DEMO = DATA_MODE == "demo"
STALE_AFTER_SECONDS = int(os.getenv("STALE_AFTER_SECONDS", "10"))
MAX_HISTORY_POINTS = 1000
MAX_HISTORY_RAW_ROWS = 50_000
MAX_JSON_BODY_BYTES = 64 * 1024


class PayloadTooLarge(ValueError):
    pass


DB_CONFIG = {
    "host": os.getenv("DB_HOST", "127.0.0.1"),
    "port": int(os.getenv("DB_PORT", "3306")),
    "user": os.getenv("DB_USER", "gridwise_user"),
    "password": os.getenv("DB_PASSWORD", "gridwise_pass"),
    "database": os.getenv("DB_DATABASE", "gridwise"),
}

FIELD_RANGES = {
    "voltage": (0.0, 300.0),
    "current": (0.0, 100.0),
    "power": (0.0, 25_000.0),
    "energy": (0.0, 1e9),
    "frequency": (45.0, 65.0),
    "power_factor": (0.0, 1.0),
}
REQUIRED_FIELDS = list(FIELD_RANGES)

DEMO_SCENARIOS = {
    "idle": {"label": "Idle / Standby", "power_range": (25, 55), "pf_range": (0.82, 0.92), "voltage_range": (229, 232)},
    "laptop": {"label": "Laptop / Electronics", "power_range": (65, 125), "pf_range": (0.88, 0.96), "voltage_range": (228, 232)},
    "heater": {"label": "Electric Heater", "power_range": (1200, 1800), "pf_range": (0.98, 1.00), "voltage_range": (226, 231)},
    "high_load_demo": {"label": "High Load (Alert Demo)", "power_range": (2050, 2300), "pf_range": (0.92, 0.98), "voltage_range": (220, 228)},
}

_state_lock = threading.Lock()
_db_lock = threading.RLock()
_db_conn = None
last_raw_values: list[dict] = []
active_scenario = "laptop"
current_average_data: dict = {
    "voltage": 0.0,
    "current": 0.0,
    "power": 0.0,
    "energy": 0.0,
    "frequency": 0.0,
    "power_factor": 0.0,
    "last_update": None,
    "samples_averaged": 0,
    "source": "synthetic" if IS_DEMO else "esp32-pzem",
    "is_simulated": IS_DEMO,
    "scenario": None,
}


def database_connection():
    """Return one reconnecting MySQL connection protected by ``_db_lock``."""
    global _db_conn
    with _db_lock:
        if _db_conn is None or not _db_conn.is_connected():
            _db_conn = mysql.connector.connect(**DB_CONFIG)
        return _db_conn


def _execute_schema() -> None:
    schema = (BASE_DIR / "schema.sql").read_text(encoding="utf-8")
    conn = database_connection()
    cursor = conn.cursor()
    try:
        for statement in (part.strip() for part in schema.split(";") if part.strip()):
            cursor.execute(statement)
        conn.commit()
    finally:
        cursor.close()


def _migrate_existing_schema() -> None:
    """Add metadata columns when reusing a Docker volume from an older demo."""
    conn = database_connection()
    cursor = conn.cursor()
    try:
        cursor.execute("SHOW COLUMNS FROM energy_measurements")
        columns = {row[0] for row in cursor.fetchall()}
        if "source" not in columns:
            cursor.execute(
                "ALTER TABLE energy_measurements "
                "ADD COLUMN source ENUM('synthetic', 'esp32-pzem') NOT NULL DEFAULT 'synthetic' AFTER measured_at"
            )
        if "scenario" not in columns:
            cursor.execute("ALTER TABLE energy_measurements ADD COLUMN scenario VARCHAR(64) NULL AFTER source")
        cursor.execute("SHOW INDEX FROM energy_measurements")
        indexes = {row[2] for row in cursor.fetchall()}
        if "idx_source_measured_at" not in indexes:
            cursor.execute("CREATE INDEX idx_source_measured_at ON energy_measurements (source, measured_at)")
        conn.commit()
    finally:
        cursor.close()


def wait_for_database(attempts: int = 30) -> None:
    last_error = None
    for attempt in range(1, attempts + 1):
        try:
            database_connection()
            _execute_schema()
            _migrate_existing_schema()
            return
        except MySQLError as exc:
            last_error = exc
            print(f"[DB] Waiting for MySQL ({attempt}/{attempts}): {exc}")
            time.sleep(2)
    raise RuntimeError(f"Could not connect to MySQL after {attempts} attempts: {last_error}")


def format_timestamp(value: datetime | str | None) -> str | None:
    if value is None:
        return None
    if isinstance(value, str):
        value = datetime.fromisoformat(value.replace("Z", "+00:00"))
    return value.isoformat(timespec="milliseconds")


def source_is_simulated(source: str | None) -> bool:
    return source == "synthetic"


def validate_and_normalize(raw_json: dict) -> tuple[dict, list[str]]:
    errors: list[str] = []
    if "pf" in raw_json and "power_factor" not in raw_json:
        raw_json["power_factor"] = raw_json["pf"]

    normalized = {}
    for field in REQUIRED_FIELDS:
        raw_val = raw_json.get(field)
        if raw_val is None:
            errors.append(f"Missing required field: '{field}'")
            continue
        try:
            value = float(raw_val)
        except (TypeError, ValueError):
            errors.append(f"Field '{field}' is not numeric: {raw_val!r}")
            continue
        lower, upper = FIELD_RANGES[field]
        if not lower <= value <= upper:
            errors.append(f"Field '{field}' out of range [{lower}, {upper}]: {value}")
            continue
        normalized[field] = value
    return normalized, errors


def compute_averages(raw: dict) -> dict:
    """Smooth instantaneous fields over five readings; never average energy."""
    with _state_lock:
        last_raw_values.append({key: raw[key] for key in ("voltage", "current", "power", "frequency", "power_factor")})
        del last_raw_values[:-5]
        count = len(last_raw_values)
        average = {
            key: sum(item[key] for item in last_raw_values) / count
            for key in ("voltage", "current", "power", "frequency", "power_factor")
        }
        average["energy"] = raw["energy"]
        average["samples_averaged"] = count
        return average


def insert_measurement(raw: dict, average: dict, measured_at: datetime, source: str, scenario: str | None) -> None:
    sql = """
        INSERT INTO energy_measurements (
            measured_at, source, scenario,
            raw_voltage, raw_current, raw_power, raw_energy, raw_frequency, raw_power_factor,
            avg_voltage, avg_current, avg_power, avg_energy, avg_frequency, avg_power_factor,
            samples_averaged
        ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
    """
    values = (
        measured_at, source, scenario,
        raw["voltage"], raw["current"], raw["power"], raw["energy"], raw["frequency"], raw["power_factor"],
        average["voltage"], average["current"], average["power"], average["energy"], average["frequency"], average["power_factor"],
        average["samples_averaged"],
    )
    with _db_lock:
        conn = database_connection()
        cursor = conn.cursor()
        try:
            cursor.execute(sql, values)
            conn.commit()
        finally:
            cursor.close()


def update_current_state(average: dict, measured_at: datetime, source: str, scenario: str | None) -> None:
    global current_average_data
    with _state_lock:
        current_average_data = {
            **average,
            "last_update": format_timestamp(measured_at),
            "source": source,
            "is_simulated": source_is_simulated(source),
            "scenario": scenario,
        }


def hydrate_latest_state() -> None:
    """Make /data useful immediately after a server restart when history exists."""
    sql = """
        SELECT measured_at, source, scenario,
               avg_voltage, avg_current, avg_power, avg_energy, avg_frequency, avg_power_factor,
               samples_averaged
        FROM energy_measurements
        WHERE source = %s
        ORDER BY measured_at DESC, id DESC
        LIMIT 1
    """
    with _db_lock:
        conn = database_connection()
        cursor = conn.cursor(dictionary=True)
        try:
            cursor.execute(sql, ("synthetic" if IS_DEMO else "esp32-pzem",))
            row = cursor.fetchone()
        finally:
            cursor.close()
    if not row:
        return
    average = {
        "voltage": float(row["avg_voltage"]),
        "current": float(row["avg_current"]),
        "power": float(row["avg_power"]),
        "energy": float(row["avg_energy"]),
        "frequency": float(row["avg_frequency"]),
        "power_factor": float(row["avg_power_factor"]),
        "samples_averaged": int(row["samples_averaged"]),
    }
    update_current_state(average, row["measured_at"], row["source"], row["scenario"])


def latest_payload() -> dict:
    with _state_lock:
        payload = dict(current_average_data)
    timestamp = payload.get("last_update")
    if timestamp:
        measured_at = datetime.fromisoformat(timestamp)
        age_seconds = max(0, (datetime.now() - measured_at).total_seconds())
    else:
        age_seconds = None
    payload["data_age_seconds"] = round(age_seconds, 1) if age_seconds is not None else None
    payload["is_fresh"] = age_seconds is not None and age_seconds <= STALE_AFTER_SECONDS
    return payload


def _parse_history_dates(params: dict) -> tuple[datetime, datetime]:
    allowed = {
        "30m": timedelta(minutes=30),
        "1h": timedelta(hours=1),
        "3h": timedelta(hours=3),
        "1d": timedelta(days=1),
    }
    start = params.get("start", [None])[0]
    end = params.get("end", [None])[0]
    if start and end:
        start_dt = datetime.fromisoformat(start.replace("Z", "+00:00").replace("T", " "))
        end_dt = datetime.fromisoformat(end.replace("Z", "+00:00").replace("T", " "))
        if end_dt < start_dt:
            raise ValueError("'end' must be later than 'start'.")
        return start_dt, end_dt
    end_dt = datetime.now()
    return end_dt - allowed.get(params.get("range", ["30m"])[0], allowed["30m"]), end_dt


def _number(value) -> float:
    return float(value) if value is not None else 0.0


def aggregate_history(rows: list[dict]) -> tuple[list[dict], bool, int]:
    """Keep the whole time range visible without returning an unmanageable table."""
    raw_count = len(rows)
    if raw_count <= MAX_HISTORY_POINTS:
        return rows, False, 1

    bucket_size = (raw_count + MAX_HISTORY_POINTS - 1) // MAX_HISTORY_POINTS
    aggregated: list[dict] = []
    average_fields = (
        "raw_voltage", "raw_current", "raw_power", "raw_frequency", "raw_power_factor",
        "avg_voltage", "avg_current", "avg_power", "avg_frequency", "avg_power_factor",
    )
    for index in range(0, raw_count, bucket_size):
        bucket = rows[index:index + bucket_size]
        latest = dict(bucket[-1])
        for field in average_fields:
            latest[field] = sum(_number(item[field]) for item in bucket) / len(bucket)
        latest["raw_energy"] = _number(bucket[-1]["raw_energy"])
        latest["avg_energy"] = _number(bucket[-1]["avg_energy"])
        latest["samples_averaged"] = max(int(item["samples_averaged"] or 0) for item in bucket)
        latest["bucket_samples"] = len(bucket)
        aggregated.append(latest)
    return aggregated, True, bucket_size


def get_history(params: dict) -> dict:
    start_dt, end_dt = _parse_history_dates(params)
    base_sql = """
        FROM energy_measurements
        WHERE source = %s AND measured_at BETWEEN %s AND %s
    """
    with _db_lock:
        conn = database_connection()
        cursor = conn.cursor(dictionary=True)
        try:
            source = "synthetic" if IS_DEMO else "esp32-pzem"
            cursor.execute("SELECT COUNT(*) AS total " + base_sql, (source, start_dt, end_dt))
            total = int(cursor.fetchone()["total"])
            cursor.execute(
                """SELECT id, measured_at, source, scenario,
                          raw_voltage, raw_current, raw_power, raw_energy, raw_frequency, raw_power_factor,
                          avg_voltage, avg_current, avg_power, avg_energy, avg_frequency, avg_power_factor,
                          samples_averaged """
                + base_sql
                + " ORDER BY measured_at DESC, id DESC LIMIT %s",
                (source, start_dt, end_dt, MAX_HISTORY_RAW_ROWS),
            )
            rows = list(reversed(cursor.fetchall()))
        finally:
            cursor.close()

    rows, aggregated, bucket_size = aggregate_history(rows)
    for row in rows:
        row["measured_at"] = format_timestamp(row["measured_at"])
        for key, value in tuple(row.items()):
            if hasattr(value, "as_tuple"):
                row[key] = float(value)
    return {
        "start": format_timestamp(start_dt),
        "end": format_timestamp(end_dt),
        "count": total,
        "displayed_count": len(rows),
        "aggregated": aggregated,
        "bucket_samples": bucket_size,
        "partial": total > MAX_HISTORY_RAW_ROWS,
        "source": "synthetic" if IS_DEMO else "esp32-pzem",
        "rows": rows,
    }


class Handler(BaseHTTPRequestHandler):
    def log_message(self, _format, *_args):
        pass

    def _send(self, body, content_type="application/json", status=200):
        if not isinstance(body, (str, bytes)):
            body = json.dumps(body, ensure_ascii=False)
        if isinstance(body, str):
            body = body.encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Access-Control-Allow-Origin", "*")
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def _json(self, body, status=200):
        self._send(body, "application/json", status)

    def _read_json(self) -> dict:
        length = int(self.headers.get("Content-Length", "0"))
        if length <= 0:
            raise ValueError("Request body is empty")
        if length > MAX_JSON_BODY_BYTES:
            raise PayloadTooLarge("Request body exceeds the 64 KB limit")
        data = json.loads(self.rfile.read(length))
        if not isinstance(data, dict):
            raise ValueError("Request body must be a JSON object")
        return data

    def _serve_frontend_asset(self, path: str) -> bool:
        """Serve the React build while preventing paths outside ``web``."""
        relative_path = path.lstrip("/")
        candidate = (WEB_DIR / relative_path).resolve()
        try:
            candidate.relative_to(WEB_DIR.resolve())
        except ValueError:
            return False
        if not candidate.is_file():
            return False
        suffixes = {
            ".js": "text/javascript; charset=utf-8",
            ".css": "text/css; charset=utf-8",
            ".svg": "image/svg+xml",
            ".png": "image/png",
            ".jpg": "image/jpeg",
            ".jpeg": "image/jpeg",
            ".ico": "image/x-icon",
            ".woff2": "font/woff2",
        }
        self._send(candidate.read_bytes(), suffixes.get(candidate.suffix.lower(), "application/octet-stream"))
        return True

    def do_GET(self):
        parsed = urlparse(self.path)
        params = parse_qs(parsed.query)
        if parsed.path == "/health":
            self._json({"ok": True, "database": "connected", "database_engine": "MySQL", "mode": DATA_MODE})
        elif parsed.path == "/data":
            self._json(latest_payload())
        elif parsed.path == "/history":
            try:
                self._json(get_history(params))
            except (ValueError, MySQLError) as exc:
                self._json({"error": str(exc)}, 400)
        elif parsed.path == "/demo/scenarios" and IS_DEMO:
            self._json({
                "scenarios": [{"id": key, "label": value["label"]} for key, value in DEMO_SCENARIOS.items()],
                "active": active_scenario,
            })
        elif parsed.path == "/":
            self._send(INDEX_FILE.read_text(encoding="utf-8"), "text/html; charset=utf-8")
        elif self._serve_frontend_asset(parsed.path):
            return
        else:
            self._json({"error": f"Route not found: {parsed.path}"}, 404)

    def do_HEAD(self):
        """Support standard deployment health checks without sending a body."""
        self.do_GET()

    def do_POST(self):
        global active_scenario
        parsed = urlparse(self.path)
        if parsed.path == "/demo/scenario":
            if not IS_DEMO:
                self._json({"error": "Route only available in DATA_MODE=demo"}, 404)
                return
            try:
                scenario = self._read_json().get("scenario", "")
            except PayloadTooLarge as exc:
                self._json({"error": str(exc)}, 413)
                return
            except (ValueError, json.JSONDecodeError) as exc:
                self._json({"error": str(exc)}, 400)
                return
            if scenario not in DEMO_SCENARIOS:
                self._json({"error": f"Unknown scenario '{scenario}'."}, 400)
                return
            active_scenario = scenario
            self._json({"ok": True, "scenario": scenario, "label": DEMO_SCENARIOS[scenario]["label"]})
            return

        if parsed.path != "/data":
            self._json({"error": f"Route not found: {parsed.path}"}, 404)
            return

        try:
            raw_json = self._read_json()
        except PayloadTooLarge as exc:
            self._json({"error": str(exc)}, 413)
            return
        except (ValueError, json.JSONDecodeError) as exc:
            self._json({"error": str(exc)}, 400)
            return

        expected_source = "synthetic" if IS_DEMO else "esp32-pzem"
        source = raw_json.get("source", expected_source)
        if source != expected_source:
            self._json({"error": f"{DATA_MODE} mode accepts only source='{expected_source}'."}, 403)
            return
        if IS_DEMO and raw_json.get("is_simulated", True) is not True:
            self._json({"error": "Demo mode accepts only explicitly simulated telemetry."}, 403)
            return
        if not IS_DEMO and raw_json.get("is_simulated", False) is True:
            self._json({"error": "Hardware mode rejects simulated telemetry."}, 403)
            return

        normalized, errors = validate_and_normalize(raw_json)
        if errors:
            self._json({"error": "Validation failed", "details": errors}, 400)
            return
        scenario = raw_json.get("scenario") if IS_DEMO else None
        if IS_DEMO and scenario not in DEMO_SCENARIOS:
            self._json({"error": "Demo telemetry must include a valid scenario."}, 400)
            return

        measured_at = datetime.now()
        average = compute_averages(normalized)
        try:
            insert_measurement(normalized, average, measured_at, source, scenario)
        except MySQLError as exc:
            self._json({"error": f"Database write failed: {exc}"}, 500)
            return
        update_current_state(average, measured_at, source, scenario)
        self._json({"ok": True, "last_update": format_timestamp(measured_at)})

    def do_OPTIONS(self):
        self.send_response(204)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.end_headers()


if __name__ == "__main__":
    print("=" * 60)
    print("  GridWise Energy Monitor — MySQL API server")
    print(f"  Mode : {DATA_MODE.upper()}")
    print(f"  Port : {PORT}")
    print(f"  DB   : MySQL at {DB_CONFIG['host']}:{DB_CONFIG['port']}/{DB_CONFIG['database']}")
    print("=" * 60)
    wait_for_database()
    hydrate_latest_state()
    print("  ✓ MySQL schema ready.")
    print(f"  Dashboard → http://localhost:{PORT}/")
    HTTPServer(("0.0.0.0", PORT), Handler).serve_forever()
